options.getOption:
const s = context.panel.data.series[0];
const fields = s?.fields ?? [];
const codes = fields.find((f) => f.name === 'country')?.values ?? [];
const counted = fields.find((f) => f.name !== 'country');
const unit = counted?.name ?? 'count';
const counts = counted?.values ?? [];

// The world map names countries in English. Intl supplies most of those names from the
// two-letter code Cloudflare reports; these are the ones where the map's name differs.
const ALIASES = {
  BA: 'Bosnia and Herzegovina',
  BS: 'The Bahamas',
  CD: 'Democratic Republic of the Congo',
  CG: 'Republic of the Congo',
  CI: 'Ivory Coast',
  CZ: 'Czech Republic',
  GW: 'Guinea Bissau',
  MK: 'Macedonia',
  MM: 'Myanmar',
  RS: 'Republic of Serbia',
  SZ: 'Swaziland',
  TL: 'East Timor',
  TR: 'Turkey',
  TT: 'Trinidad and Tobago',
  TZ: 'United Republic of Tanzania',
  US: 'United States of America',
};
const regions = new Intl.DisplayNames(['en'], { type: 'region' });
const nameOf = (code) => {
  if (ALIASES[code]) return ALIASES[code];
  try {
    return regions.of(code);
  } catch {
    return code;
  }
};

const data = codes.map((code, i) => ({ name: nameOf(code), value: counts[i] }));
const max = Math.max(1, ...data.map((d) => d.value));
const theme = context.grafana.theme;

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    formatter: (p) => `${p.name}: ${Number.isFinite(p.value) ? p.value : 0} ${unit}`,
  },
  visualMap: {
    min: 0,
    max,
    left: 'left',
    bottom: 0,
    calculable: true,
    text: [`More ${unit}`, 'Fewer'],
    inRange: { color: ['#c6dbef', '#08306b'] },
    textStyle: { color: theme.colors.text.secondary },
  },
  series: [
    {
      name: unit,
      type: 'map',
      map: 'world',
      // Top and bottom set the map's height to the panel's; ECharts keeps the aspect ratio.
      top: 8,
      bottom: 8,
      roam: true,
      scaleLimit: { min: 1, max: 12 },
      itemStyle: {
        areaColor: theme.colors.background.secondary,
        borderColor: theme.colors.border.medium,
      },
      emphasis: { label: { show: false }, itemStyle: { areaColor: '#f2cc0c' } },
      select: { disabled: true },
      data,
    },
  ],
};
